// Prépare le rappel J-7 / J-1 pour le rendez-vous courant
const apt = $('Loop Appointments').item.json;
const patient = $json;

// N'envoyer un rappel que pour les RDV confirmés ou en attente.
const st = String(apt.status || '').toLowerCase();
if (!(st === 'confirmed' || st === 'pending')) return [];

const TZ_OPTS = { timeZone: 'Africa/Tunis' };
const ymdFmt = new Intl.DateTimeFormat('en-CA', { ...TZ_OPTS, year: 'numeric', month: '2-digit', day: '2-digit' });
const tunisDayUtcMidnight = (dateObj) => {
  const parts = {};
  for (const part of ymdFmt.formatToParts(dateObj)) parts[part.type] = part.value;
  return Date.UTC(Number(parts.year), Number(parts.month) - 1, Number(parts.day));
};

const todayMidnight = tunisDayUtcMidnight(new Date());
const rdvDate = new Date(apt.scheduled_at);
const rdvMidnight = tunisDayUtcMidnight(rdvDate);
const daysUntil = Math.round((rdvMidnight - todayMidnight) / 86400000);

let reminder_type = null;
let notification_type = null;
if (daysUntil === 7) { reminder_type = 'j7'; notification_type = 'APPOINTMENT_REMINDER_7'; }
else if (daysUntil === 1) { reminder_type = 'j1'; notification_type = 'APPOINTMENT_REMINDER_1'; }
if (!reminder_type) return [];

const dateStr = rdvDate.toLocaleDateString('fr-FR', { ...TZ_OPTS, day: '2-digit', month: '2-digit', year: 'numeric' });
const timeStr = rdvDate.toLocaleTimeString('fr-FR', { ...TZ_OPTS, hour: '2-digit', minute: '2-digit' });
const patientName = `${patient.first_name || ''} ${patient.last_name || ''}`.trim() || 'Patient';
let doctorName = apt.doctor_name || 'Médecin';

doctorName = doctorName || 'Médecin';

// Sujets d'email selon la demande
const subject = reminder_type === 'j7'
  ? 'Rappel de rendez-vous médical - J-7'
  : 'Rappel de rendez-vous médical - Demain';

const typeLabel = reminder_type === 'j7' ? 'Rappel 7 jours avant' : 'Rappel 1 jour avant';

const message = `Bonjour ${patientName}, votre rendez-vous médical est prévu le ${dateStr} à ${timeStr}. Médecin: ${doctorName}. Type: ${typeLabel}.`;

const gmail_html = `<html><body>
<h2>Rappel de rendez-vous médical</h2>
<p>Bonjour <strong>${patientName}</strong>,</p>
<p>Nous vous rappelons que votre rendez-vous médical est prévu le :</p>
<ul>
<li><strong>Date:</strong> ${dateStr}</li>
<li><strong>Heure:</strong> ${timeStr}</li>
<li><strong>Médecin:</strong> ${doctorName}</li>
<li><strong>Type de notification:</strong> ${typeLabel}</li>
</ul>
<p>Cordialement,<br/>MedSecretariat</p>
</body></html>`;

// Destinataire test pendant la phase de test
const TEST_EMAIL = 'azizzeiri7@gmail.com';
const useTestEmail = true;
const toEmail = useTestEmail ? TEST_EMAIL : (patient.email || TEST_EMAIL);

return [{
  json: {
    patient_id: apt.patient_id,
    appointment_id: apt.id,
    patient_name: patientName,
    patient_email: toEmail,
    title: subject,
    message: message,
    gmail_html: gmail_html,
    reminder_type: reminder_type,
    notification_type: notification_type,
    dedup_key: `appointment:${apt.patient_id}:${apt.id}:${notification_type}`
  }
}];
